--
-- Table structure for table `vocab_subcategories`
--

DROP TABLE IF EXISTS `vocab_subcategories`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vocab_subcategories` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `vocab_category_id` bigint unsigned NOT NULL,
  `name_en` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_jp` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_romaji` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `icon_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `icon_thumbnail_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `icon_thumbnail_bg` smallint unsigned NOT NULL DEFAULT '99',
  `audio_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` smallint unsigned NOT NULL DEFAULT '99',
  `is_premium` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `vocab_subcategories_vocab_category_id_foreign` (`vocab_category_id`),
  CONSTRAINT `vocab_subcategories_vocab_category_id_foreign` FOREIGN KEY (`vocab_category_id`) REFERENCES `vocab_categories` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=223 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

