--
-- Table structure for table `vocab_words`
--

DROP TABLE IF EXISTS `vocab_words`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vocab_words` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `vocab_subcategory_id` bigint unsigned NOT NULL,
  `word_jp` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `audio_jp` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sentence_jp` text COLLATE utf8mb4_unicode_ci,
  `sentence_audio_jp` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `word_romaji` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sentence_romaji` text COLLATE utf8mb4_unicode_ci,
  `word_en` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `audio_en` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sentence_en` text COLLATE utf8mb4_unicode_ci,
  `sentence_audio_en` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image_thumbnail_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image_thumbnail_bg` smallint unsigned NOT NULL DEFAULT '99',
  `voice_id` bigint unsigned DEFAULT NULL,
  `sort_order` smallint unsigned NOT NULL DEFAULT '99',
  `is_premium` tinyint(1) NOT NULL DEFAULT '0',
  `is_approved` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `vocab_words_vocab_subcategory_id_foreign` (`vocab_subcategory_id`),
  KEY `vocab_words_voice_id_foreign` (`voice_id`),
  CONSTRAINT `vocab_words_vocab_subcategory_id_foreign` FOREIGN KEY (`vocab_subcategory_id`) REFERENCES `vocab_subcategories` (`id`) ON DELETE CASCADE,
  CONSTRAINT `vocab_words_voice_id_foreign` FOREIGN KEY (`voice_id`) REFERENCES `voices` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=3883 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

